//! Lookup-only comparison. The linear baseline uses the old algorithm over a
//! mirrored FunctionRecord arena with the same layout and function IDs.
use js_runtime::{Runtime,Value,EnvId,ObjectId,FunctionId,JsResult};
use js_runtime::closures::{FunctionRecord,FunctionKind};
use std::hint::black_box;
fn noop(_: &mut Runtime,_:Value,_:&[Value],_:EnvId)->JsResult<Value>{Ok(Value::Undefined)}
fn record(object:ObjectId,env:EnvId)->FunctionRecord{FunctionRecord{kind:FunctionKind::Native{code:noop,env,strict:true,arrow_this:None},object,prototype:None,name:js_runtime::StringId(0),arity:0,source:None,lexical_new_target:Value::Undefined,constructor_default_prototype:ObjectId(0),native_construct_allocates_object:false,constructible:false}}
fn token(value:Value)->u64{match value{Value::Function(id)=>id.0 as u64,Value::Object(id)=>(id.0 as u64)^0x8000000000000000,_=>panic!()}}
fn main(){let mut rows=Vec::new();for size in[1000,10000,100000]{let mut rt=Runtime::new();let env=rt.global_env;let mut records=Vec::new();let mut callable=Vec::new();for _ in 0..size{let f=rt.native_function("benchmark",0,noop).unwrap();let Value::Function(id)=f else{panic!()};if records.is_empty(){for _ in 0..id.0{records.push(record(ObjectId(usize::MAX),env))}}let object=rt.object_id(f).unwrap();assert_eq!(records.len(),id.0);records.push(record(object,env));callable.push(object);}let ordinary=rt.object();let ordinary=rt.object_id(ordinary).unwrap();let queries=[rt.object_prototype,ordinary,callable[size/2],callable[size-1]];let linear=|object:ObjectId|records.iter().position(|f|f.object==object).map(|id|Value::Function(FunctionId(id))).unwrap_or(Value::Object(object));for object in queries{assert_eq!(linear(object),rt.value_for_object(object));}for repeat in 0..5{let iterations=1024;let mut old_checksum=0u64;let begin=std::time::Instant::now();for i in 0..iterations{let object=black_box(queries[i%queries.len()]);let result=black_box(&records).iter().position(|f|f.object==object).map(|id|Value::Function(FunctionId(id))).unwrap_or(Value::Object(object));old_checksum=old_checksum.wrapping_mul(31).wrapping_add(token(black_box(result)));}let old_ns=begin.elapsed().as_nanos();let mut checksum=0u64;let begin=std::time::Instant::now();for i in 0..iterations{let object=black_box(queries[i%queries.len()]);checksum=checksum.wrapping_mul(31).wrapping_add(token(black_box(rt.value_for_object(object))));}let index_ns=begin.elapsed().as_nanos();assert_eq!(checksum,old_checksum);rows.push(format!("{{\"functions\":{},\"repeat\":{repeat},\"queries\":{iterations},\"linearNs\":{old_ns},\"indexedNs\":{index_ns},\"checksum\":\"{checksum:016x}\"}}",records.len()));}}println!("[{}]",rows.join(","));}
